import fs from 'node:fs/promises'
import path from 'node:path'
import crypto from 'node:crypto'

const distDir = path.resolve(process.argv[2] || 'dist')
const manifestPath = path.join(distDir, 'integrity-manifest.json')
const manifest = JSON.parse(await fs.readFile(manifestPath, 'utf8'))
const failures = []

for (const record of manifest.files || []) {
  const absolute = path.resolve(distDir, record.path)
  if (!absolute.startsWith(`${distDir}${path.sep}`)) {
    failures.push(`잘못된 경로: ${record.path}`)
    continue
  }
  try {
    const content = await fs.readFile(absolute)
    const digest = crypto.createHash('sha256').update(content).digest('hex')
    if (digest !== record.sha256 || content.byteLength !== record.size) failures.push(`checksum 불일치: ${record.path}`)
  } catch {
    failures.push(`파일 없음: ${record.path}`)
  }
}

if (failures.length) {
  console.error(failures.join('\n'))
  process.exit(1)
}

console.log(`[integrity] OK: ${manifest.files.length} files`)


FILE upgrade/admin-v2/scripts/generate-integrity-manifest.mjs
import fs from 'node:fs/promises'
import path from 'node:path'
import crypto from 'node:crypto'

const distDir = path.resolve(process.argv[2] || 'dist')
const manifestName = 'integrity-manifest.json'

async function walk(dir) {
  const entries = await fs.readdir(dir, { withFileTypes: true })
  const files = []
  for (const entry of entries) {
    const absolute = path.join(dir, entry.name)
    if (entry.isDirectory()) files.push(...(await walk(absolute)))
    else files.push(absolute)
  }
  return files
}

const packageJson = JSON.parse(await fs.readFile(new URL('../package.json', import.meta.url), 'utf8'))
const files = (await walk(distDir))
  .filter((file) => path.basename(file) !== manifestName)
  .sort((a, b) => a.localeCompare(b))

const records = []
for (const file of files) {
  const content = await fs.readFile(file)
  records.push({
    path: path.relative(distDir, file).split(path.sep).join('/'),
    size: content.byteLength,
    sha256: crypto.createHash('sha256').update(content).digest('hex'),
  })
}

const manifest = {
  schemaVersion: 1,
  application: packageJson.name,
  version: packageJson.version,
  commit: process.env.CI_COMMIT_SHA || process.env.GIT_COMMIT || 'local',
  files: records,
}

await fs.writeFile(path.join(distDir, manifestName), `${JSON.stringify(manifest, null, 2)}\n`)
console.log(`[integrity] manifest generated: ${records.length} files`)


